window.DEX_DATA["sources:backport-97e026af38edc3f3"]={"json":{"skins":[{"filename":"littlegirl.png"}],"names":[{"name":"贝蒂"},{"name":"苏茜"},{"name":"莫莉"},{"name":"蒂莉"},{"name":"霍莉"}],"chat":[{"lines":[{"text":"我不跟你说话！你是陌生人！"},{"text":"当陌生人是什么感觉？"}]},{"lines":[{"text":"哼，我衣柜里的宝可梦都比你的厉害，我还有火焰鸟呢！"},{"text":"玩具火焰鸟又怎样？你连玩具都没有！"}]},{"lines":[{"text":"你来抓宝可梦吗？是不是很吓人的那种？"},{"text":"要是有超级无敌魔法精灵球，我肯定也能抓到吓人的宝可梦！"}]},{"lines":[{"text":"你怕宝可梦吗？我一点都不怕！嗯，没那么怕……"},{"text":"有些宝可梦还是有一点吓人，我只喜欢毛茸茸的。"}]}]}};
